//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:						HE_EWMA
//	CREATOR:					Helgevold - Jan Magne Dybvik
// REQUIREMENTS: 		NX CPU
//
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN							DESCRIPTION
//	 1.0.0				2023-11-07		Jan Magne Dybvik		Initial release
//	 2.0.0				2025-03-25		William Veim				Rework
//
//================================================================================================================================
//
//			DESCRTIPTION: 	
//			Filter where the latest values are weighted more than older values
//		
//===============================================================================================================================

// Initialize
IF P_First_Run THEN
	Wrk_Value := Inp_Vaule;
END_IF;

// Get task interval in seconds
Wrk_TaskTime := GetMyTaskInterval();
Wrk_Interval := LINT_TO_REAL(TimeToNanoSec(Wrk_TaskTime)) / 1000000000.0;

// Get time Constant
Wrk_TimeCoefficient := (1.0 / Cfg_TC);

 IF (Cfg_TC <= 0.0) THEN
    Wrk_Value := Inp_Vaule;
END_IF;
 
// Exponentially Weighted Moving Average
 IF (Wrk_TaskTime <> T#0ms AND Cfg_TC > 0.0) THEN
	Wrk_Value := ((Inp_Vaule - Wrk_Value) * Wrk_TimeCoefficient * Wrk_Interval) + Wrk_Value;
 END_IF;
 
 IF Inp_ResetFilter THEN
    Wrk_Value := Inp_Vaule;
END_IF;
 
Out_Value := Wrk_Value;
